import{_ as t,c as a,o,aj as i}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Interface: GetOrCreateWithAliasOptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/GetOrCreateWithAliasOptions.md","filePath":"reference/js-bao-wss-client/api/interfaces/GetOrCreateWithAliasOptions.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/GetOrCreateWithAliasOptions.md"};function s(n,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / GetOrCreateWithAliasOptions</p><h1 id="interface-getorcreatewithaliasoptions" tabindex="-1">Interface: GetOrCreateWithAliasOptions <a class="header-anchor" href="#interface-getorcreatewithaliasoptions" aria-label="Permalink to “Interface: GetOrCreateWithAliasOptions”">​</a></h1><p>Options for getting an existing document by alias, or creating a new one if the alias does not exist.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="alias" tabindex="-1">alias <a class="header-anchor" href="#alias" aria-label="Permalink to “alias”">​</a></h3><blockquote><p><strong>alias</strong>: <a href="./ResolveAliasParams.html"><code>ResolveAliasParams</code></a></p></blockquote><p>The alias to look up or assign to the new document.</p><hr><h3 id="documentformat" tabindex="-1">documentFormat? <a class="header-anchor" href="#documentformat" aria-label="Permalink to “documentFormat?”">​</a></h3><blockquote><p><code>optional</code> <strong>documentFormat?</strong>: <code>1</code> | <code>2</code></p></blockquote><p>Create a LARGE document (<code>2</code>) instead of an ordinary one, with the same meaning it has on <a href="./CreateDocumentOptions.html#documentformat">CreateDocumentOptions.documentFormat</a>.</p><p>On this idempotent route it is read twice over: applied when the call creates the document, and otherwise taken as a statement about the document the alias already names. If the stored format differs the call is REFUSED (<code>DOCUMENT_FORMAT_MISMATCH</code>), because an app that asks for a large document and is handed an ordinary one has already made the mistake this route exists to prevent; if it agrees, the format is echoed back.</p><p>Omitted — the default — states nothing, so an existing binding is answered exactly as it was before this option existed. Any value other than <code>1</code> or <code>2</code>, including the string <code>&quot;2&quot;</code>, is refused with <code>INVALID_ARGUMENT</code> before any request is made.</p><hr><h3 id="metadata" tabindex="-1">metadata? <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>metadata?</strong>: <code>unknown</code></p></blockquote><p>Opaque JSON-serializable metadata blob to attach if a new document is created (≤ 4 KB serialized UTF-8). Like <code>tags</code>, it applies only when this call creates the document; an existing binding is left untouched.</p><hr><h3 id="tags" tabindex="-1">tags? <a class="header-anchor" href="#tags" aria-label="Permalink to “tags?”">​</a></h3><blockquote><p><code>optional</code> <strong>tags?</strong>: <code>string</code>[]</p></blockquote><p>Tags to attach if a new document is created.</p><hr><h3 id="title" tabindex="-1">title? <a class="header-anchor" href="#title" aria-label="Permalink to “title?”">​</a></h3><blockquote><p><code>optional</code> <strong>title?</strong>: <code>string</code></p></blockquote><p>The title to use if a new document is created.</p>',27)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
